  "parameters": {},
  "distinguishes": ["H1", "H3"],
  "prediction": {
    "scoring_status": "numeric",
    "metric_key": "trial_random_trial_ba_mean",
    "primary_direction": "near_zero",
    "threshold": 0.05,
    "check_facts": [],
    "conditional_predictions": [
      {"hypothesis_id": "H1", "direction": "positive", "rationale": "If trial content drives performance, randomizing labels at the trial level should break any task mapping for each new label configuration, reducing BA to chance."},
      {"hypothesis_id": "H3", "direction": "negative", "rationale": "If session identity effects drive performance, permuting labels within trials while preserving class counts might still allow metadata-based prediction if sessions are preserved; however, the tool randomizes at trial level so this is less clear. We expect near-zero gap as a baseline."}
    ],
    "update_rule_if_opposite": "If BA remains high after shuffling (positive direction), H3 gains support over H1 regarding identity effects persisting despite label permutation."
  },
